"""Midnight Bat Club — run with: streamlit run app.py

Streamlit hosts the app; the embedded Canvas game runs in the browser.
No external game assets or additional Python dependencies required.
"""
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
    page_title="Midnight Bat Club",
    page_icon="🏏",
    layout="wide",
    initial_sidebar_state="collapsed",
)

st.markdown(
    """<style>
    .block-container {padding-top: 1rem; padding-bottom: 0; max-width: 1250px;}
    </style>""",
    unsafe_allow_html=True,
)
st.caption("Click inside the game to focus keyboard controls. Desktop keyboard + mouse recommended.")

GAME_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sahur • Midnight Bat Club</title><style>\n:root{color-scheme:dark;--lime:#dcff70;--muted:#a7b4a0}*{box-sizing:border-box}body{margin:0;background:#101610;color:#edf5df;font:14px ui-monospace,Consolas,monospace}header,main,footer{max-width:1180px;margin:auto;padding:20px 26px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #33412e}header b{letter-spacing:3px}small,.muted{color:var(--muted)}.tag{border:1px solid #5e7540;padding:6px 10px;color:var(--lime);font-size:11px}h1{font-size:clamp(30px,5vw,58px);letter-spacing:-3px;margin:10px 0}h1 span{color:var(--lime)}.intro{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:12px 0 24px}.intro p{max-width:400px;line-height:1.7;color:var(--muted)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:18px}.arena{position:relative;border:1px solid #526341;background:#15251c;overflow:hidden}canvas{display:block;width:100%;aspect-ratio:4/3;image-rendering:pixelated;touch-action:none;cursor:none}.hud{display:flex;justify-content:space-between;padding:12px;background:#1b2519;border-bottom:1px solid #526341;font-size:12px;gap:8px;flex-wrap:wrap}.hud strong{color:var(--lime)}.overlay{position:absolute;inset:41px 0 0;display:flex;align-items:center;justify-content:center;background:#0c160edb;text-align:center;padding:24px}.overlay[hidden]{display:none}.overlay h2{font-size:30px;letter-spacing:-1px}.overlay p{max-width:420px;line-height:1.8;color:#c2cfb4}.overlay button{margin:8px}.panel{background:#192217;border:1px solid #3f4f34;padding:18px}.panel h2{font-size:15px;margin:0 0 8px}.wallet{font-size:32px;color:var(--lime);margin:12px 0 22px}button{background:var(--lime);border:0;padding:12px 16px;color:#18200f;font: bold 12px ui-monospace,monospace;cursor:pointer}button:hover{filter:brightness(1.1)}button:disabled{opacity:.4;cursor:not-allowed}.upgrade{display:block;width:100%;text-align:left;background:#273222;color:#edf5df;border:1px solid #4b5d3c;margin-top:10px;padding:12px}.upgrade span{display:block;font-size:11px;color:#bdcbaa;margin:5px 0}.upgrade b{color:var(--lime)}.controls{display:flex;gap:10px;flex-wrap:wrap;padding:14px 0}.controls button{background:#283322;color:#dce8cf;border:1px solid #4a5a3c}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:22px}.guide article{border-top:2px solid #566b3e;padding:12px 0;line-height:1.7;font-size:12px}.guide b{color:var(--lime)}footer{color:#92a285;font-size:11px;display:flex;justify-content:space-between;gap:15px}#toast{min-height:35px;color:var(--lime);font-size:12px;line-height:1.6;margin-top:14px}@media(max-width:820px){.layout{grid-template-columns:1fr}.intro{display:block}.panel{padding:14px}.wallet{margin:8px 0}.guide{grid-template-columns:1fr}header,main,footer{padding:16px}.intro p{max-width:none}.upgrade{display:inline-block;width:calc(50% - 6px);margin-right:4px;vertical-align:top}}\n</style></head><body><header><b>MB / MIDNIGHT BAT CLUB</b><span class="tag">PIXEL AIM SURVIVAL</span></header><main><div class="intro"><div><small>01 / THE NIGHT SHIFT</small><h1>TUNG TUNG.<br><span>DON’T MISS.</span></h1></div><p>You. A wooden bat. A sky full of trouble.<br>Hunt yellow orbs, build your loadout, and survive a night that refuses to slow down.</p></div><div class="layout"><section><div class="arena"><div class="hud"><span>TIME <strong id="clock">00:00</strong></span><span>SCORE <strong id="score">0</strong></span><span>HP <strong id="hp">100</strong></span><span>HEAT <strong id="heat">1.0×</strong></span></div><canvas id="game" width="800" height="600" aria-label="Pixel-art bat aim-training arena"></canvas><div class="overlay" id="overlay"><div><small id="overline">THE BALLS ARE GETTING RESTLESS</small><h2 id="title">CLOCK IN. SWING HARD.</h2><p id="description">WASD / arrows to move. Mouse to aim. Click or Space to swing.<br>Get close and put the target inside your bat’s arc.<br>Press E for the shop. Escaped balls cost health.</p><button id="start">START THE NIGHT →</button></div></div></div><div class="controls"><button id="pause">PAUSE [P]</button><button id="shop">SHOP [E]</button><button id="sound">SOUND: OFF</button><button id="restart">RESTART</button></div><small id="stats">ACCURACY — · HITS 0 · GOLD 0 · BEST 0</small></section><aside class="panel"><small>02 / YOUR LOADOUT</small><h2 style="margin-top:12px">NIGHT MARKET</h2><div class="wallet"><span id="coins">0</span> <small>PTS</small></div><small>Open the shop [E] to buy.<br>The clock pauses while shopping.</small><div id="upgrades"></div><div id="toast" role="status" aria-live="polite">Golden spawn chance: 0.5% per ball.<br>Golden reward: 20× base points.</div></aside></div><div class="guide"><article><b>01 / AIM, THEN COMMIT</b><br>Aim your bat with the mouse. A thin arc marks your reach. Golden orbs need a tighter, more accurate swing.</article><article><b>02 / BUILD A BETTER BAT</b><br>Spend hit points on reach, swing speed, movement, and score. Patch up when the night bites back.</article><article><b>03 / NO HAPPY ENDING</b><br>Speed, spawns, and evasion rise with active playtime. At 20:00, the midnight storm takes over.</article></div></main><footer><span>ORIGINAL PIXEL ART / FAN-MADE CHARACTER INTERPRETATION</span><span>NO INSTALL · NO TRACKING · LOCAL BEST SCORE</span></footer><script>\n\'use strict\';\nconst canvas=document.getElementById(\'game\'),ctx=canvas.getContext(\'2d\');ctx.imageSmoothingEnabled=false;\nconst $=id=>document.getElementById(id),W=800,H=600,TAU=Math.PI*2;\nconst keys=new Set(),mouse={x:500,y:300};let mode=\'ready\',time=0,score=0,coins=0,hp=100,hits=0,swings=0,golds=0,best=0,last=0,spawn=0,cooldown=0,swingFX=0,flash=0,balls=[],particles=[],popups=[],muted=true,audio=null;\ntry{best=Number(localStorage.getItem(\'sahurBest\'))||0}catch(e){}\nlet player={x:400,y:300},levels={reach:0,tempo:0,boots:0,bounty:0};\nconst items=[{id:\'reach\',name:\'LONGER BAT\',desc:\'+9 px reach / level\',base:80,max:10},{id:\'tempo\',name:\'QUICK HANDS\',desc:\'12% faster swings / level\',base:100,max:10},{id:\'boots\',name:\'NIGHT RUNNER\',desc:\'+22 movement speed / level\',base:75,max:8},{id:\'bounty\',name:\'BOUNTY HUNTER\',desc:\'+25% points / level\',base:120,max:10},{id:\'heal\',name:\'PATCH UP\',desc:\'Restore 35 HP\',base:140,max:Infinity}];\nfunction price(i){return i.id===\'heal\'?140:Math.floor(i.base*1.65**levels[i.id])}\nfunction renderShop(){ $(\'upgrades\').replaceChildren();for(const i of items){let b=document.createElement(\'button\');b.className=\'upgrade\';let level=levels[i.id]||0,maxed=level>=i.max;b.innerHTML=i.name+(i.id===\'heal\'?\'\':` <small>LV ${level}/${i.max}</small>`)+`<span>${i.desc}</span><b>${maxed?\'MAXED\':price(i)+\' PTS\'}</b>`;b.disabled=mode!==\'shop\'||maxed||coins<price(i)||(i.id===\'heal\'&&hp>=100);b.onclick=()=>buy(i);$(\'upgrades\').append(b)}}\nfunction buy(i){if(mode!==\'shop\'||coins<price(i)||(levels[i.id]||0)>=i.max||(i.id===\'heal\'&&hp>=100))return;coins-=price(i);if(i.id===\'heal\')hp=Math.min(100,hp+35);else levels[i.id]++;tone(660,.07);hud();renderShop()}\nfunction hud(){$(\'clock\').textContent=Math.floor(time/60).toString().padStart(2,\'0\')+\':\'+Math.floor(time%60).toString().padStart(2,\'0\');$(\'score\').textContent=score.toLocaleString();$(\'coins\').textContent=coins.toLocaleString();$(\'hp\').textContent=Math.ceil(hp);$(\'heat\').textContent=heat().toFixed(1)+\'×\';$(\'stats\').textContent=`ACCURACY ${swings?Math.round(hits/swings*100)+\'%\':\'—\'} · HITS ${hits} · GOLD ${golds} · BEST ${best.toLocaleString()}`}\nfunction heat(){return 1+2*(time/1200)**1.4+Math.max(0,time-1080)/30+Math.max(0,time-1200)/8}\nfunction tone(freq,duration){if(muted)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type=\'square\';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(e){}}\nfunction overlay(title,description,button,overline){$(\'title\').textContent=title;$(\'description\').textContent=description;$(\'start\').textContent=button;$(\'overline\').textContent=overline;$(\'overlay\').hidden=false}\nfunction reset(){time=0;score=0;coins=0;hp=100;hits=0;swings=0;golds=0;balls=[];particles=[];popups=[];spawn=.6;cooldown=0;swingFX=0;flash=0;player={x:400,y:300};levels={reach:0,tempo:0,boots:0,bounty:0};mode=\'playing\';keys.clear();$(\'overlay\').hidden=true;hud();renderShop()}\nfunction pause(){if(mode===\'playing\'){mode=\'paused\';overlay(\'TAKE A BREATHER.\',\'Your run is paused. The night can wait.\',\'RESUME →\',\'OFF THE CLOCK\')}else if(mode===\'paused\'){mode=\'playing\';$(\'overlay\').hidden=true}renderShop()}\nfunction shop(){if(mode===\'playing\'){mode=\'shop\';overlay(\'NIGHT MARKET\',\'Spend your points in the loadout panel. Score is yours to keep; only your wallet is spent.\',\'BACK TO THE NIGHT →\',\'TIME IS PAUSED\')}else if(mode===\'shop\'){mode=\'playing\';$(\'overlay\').hidden=true}renderShop()}\n$(\'start\').onclick=()=>{if(mode===\'ready\'||mode===\'dead\')reset();else if(mode===\'shop\')shop();else pause()};$(\'pause\').onclick=pause;$(\'shop\').onclick=shop;$(\'restart\').onclick=reset;$(\'sound\').onclick=()=>{muted=!muted;$(\'sound\').textContent=\'SOUND: \'+(muted?\'OFF\':\'ON\');tone(440,.05)};\nwindow.addEventListener(\'keydown\',e=>{if([\'Space\',\'ArrowUp\',\'ArrowDown\',\'ArrowLeft\',\'ArrowRight\'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code===\'KeyP\'||e.code===\'Escape\')pause();if(e.code===\'KeyE\')shop();if(e.code===\'Space\')swing()});window.addEventListener(\'keyup\',e=>keys.delete(e.code));window.addEventListener(\'blur\',()=>{keys.clear();if(mode===\'playing\')pause()});document.addEventListener(\'visibilitychange\',()=>{if(document.hidden&&mode===\'playing\')pause()});\nfunction pointer(e){let r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height}canvas.addEventListener(\'pointermove\',pointer);canvas.addEventListener(\'pointerdown\',e=>{e.preventDefault();pointer(e);swing()});\nfunction addBall(){let gold=Math.random()<.005,angle=Math.random()*TAU;let x=35+Math.random()*730,y=35+Math.random()*530;if(Math.hypot(x-player.x,y-player.y)<110){x=player.x<400?740:60;y=player.y<300?540:60}balls.push({x,y,vx:Math.cos(angle),vy:Math.sin(angle),gold,r:gold?7:10,age:0,seed:Math.random()*100,ttl:gold?Math.max(2,6/Math.sqrt(heat())):Math.max(1.2,12/Math.sqrt(heat()))})}\nfunction angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}\nfunction swing(){if(mode!==\'playing\'||cooldown>0)return;swings++;cooldown=.38*.88**levels.tempo;swingFX=.15;const a=Math.atan2(mouse.y-player.y,mouse.x-player.x),reach=70+levels.reach*9;let target=null,closest=Infinity;for(const b of balls){let d=Math.hypot(b.x-player.x,b.y-player.y);if(d<=reach+b.r&&Math.abs(angleDiff(Math.atan2(b.y-player.y,b.x-player.x),a))<(b.gold?.18:.42)+Math.atan2(b.r,Math.max(1,d))&&d<closest){target=b;closest=d}}if(target){let reward=Math.round(10*(1+.25*levels.bounty))*(target.gold?20:1);score+=reward;coins+=reward;hits++;if(target.gold)golds++;balls.splice(balls.indexOf(target),1);for(let i=0;i<14;i++){let t=Math.random()*TAU,s=50+Math.random()*160;particles.push({x:target.x,y:target.y,vx:Math.cos(t)*s,vy:Math.sin(t)*s,life:.45,c:target.gold?\'#ffad32\':\'#e8fa6c\'})}popups.push({x:target.x,y:target.y,text:\'+\'+reward,life:.9,gold:target.gold});tone(target.gold?1050:480,.08);if(target.gold)$(\'toast\').textContent=\'GOLD CAUGHT! +\'+reward+\' points. Rare work.\';renderShop()}else tone(130,.045);hud()}\nfunction end(){mode=\'dead\';best=Math.max(best,score);try{localStorage.setItem(\'sahurBest\',String(best))}catch(e){}overlay(\'THE NIGHT WINS.\',`Survived ${$(\'clock\').textContent} · ${score.toLocaleString()} points · ${hits} hits · ${golds} golden. Accuracy ${swings?Math.round(hits/swings*100):0}%. Buy earlier. Aim closer. Go again.`,\'ONE MORE NIGHT →\',\'SHIFT COMPLETE\');hud();renderShop()}\nfunction update(dt){time+=dt;cooldown=Math.max(0,cooldown-dt);swingFX=Math.max(0,swingFX-dt);flash=Math.max(0,flash-dt);let dx=(keys.has(\'KeyD\')||keys.has(\'ArrowRight\')?1:0)-(keys.has(\'KeyA\')||keys.has(\'ArrowLeft\')?1:0),dy=(keys.has(\'KeyS\')||keys.has(\'ArrowDown\')?1:0)-(keys.has(\'KeyW\')||keys.has(\'ArrowUp\')?1:0),len=Math.hypot(dx,dy)||1,speed=200+22*levels.boots;player.x=Math.max(18,Math.min(W-18,player.x+dx/len*speed*dt));player.y=Math.max(25,Math.min(H-20,player.y+dy/len*speed*dt));let h=heat();spawn-=dt;while(spawn<=0){addBall();spawn+=Math.max(.045,1.45/h**1.2)}for(let i=balls.length-1;i>=0;i--){let b=balls[i];b.age+=dt;let a=Math.atan2(b.vy,b.vx)+Math.sin(time*3.4+b.seed)*dt*(b.gold?5:1.1);if(b.gold&&Math.hypot(b.x-player.x,b.y-player.y)<150){let away=Math.atan2(b.y-player.y,b.x-player.x);a+=angleDiff(away,a)*Math.min(1,dt*4)}b.vx=Math.cos(a);b.vy=Math.sin(a);let s=(65+Math.min(time/10,100))*h**.6*(b.gold?1.85:1);b.x+=b.vx*s*dt;b.y+=b.vy*s*dt;if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)}if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)}if(b.y<b.r){b.y=b.r;b.vy=Math.abs(b.vy)}if(b.y>H-b.r){b.y=H-b.r;b.vy=-Math.abs(b.vy)}if(b.age>b.ttl){balls.splice(i,1);hp-=b.gold?5:8;flash=.12;tone(65,.06)}}for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);for(let p of popups){p.y-=30*dt;p.life-=dt}popups=popups.filter(p=>p.life>0);if(hp<=0){hp=0;end()}hud()}\nfunction rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}\nfunction draw(){ctx.fillStyle=\'#15251c\';ctx.fillRect(0,0,W,H);for(let y=0;y<H;y+=40)for(let x=0;x<W;x+=40){rect(x,y,1,1,\'#385035\');if((x/40+y/40)%3===0)rect(x+16,y+18,3,2,\'#203621\')}ctx.strokeStyle=\'#3a4e32\';ctx.lineWidth=2;ctx.strokeRect(12,12,W-24,H-24);ctx.save();ctx.globalAlpha=.13;ctx.strokeStyle=\'#c4d89b\';ctx.beginPath();ctx.arc(400,300,120,0,TAU);ctx.stroke();ctx.beginPath();ctx.moveTo(400,12);ctx.lineTo(400,588);ctx.stroke();ctx.restore();\nfor(const b of balls){let x=Math.round(b.x),y=Math.round(b.y),r=b.r;ctx.save();ctx.globalAlpha=1-.45*Math.max(0,(b.age/b.ttl-.7)/.3);rect(x-r+3,y-r,2*r-6,2*r,b.gold?\'#ffad32\':\'#d2d650\');rect(x-r,y-r+3,2*r,2*r-6,b.gold?\'#ffad32\':\'#d2d650\');rect(x-r+3,y-r+3,r,5,b.gold?\'#fff2a6\':\'#ffffb1\');rect(x+2,y+3,r-2,4,b.gold?\'#bc6d22\':\'#929d35\');if(b.gold){ctx.strokeStyle=\'#ffe6a0\';ctx.strokeRect(x-12,y-12,24,24);rect(x-2,y-18,4,4,\'#fff4bd\')}ctx.restore();ctx.fillStyle=\'#67774b\';ctx.fillRect(x-10,y+r+5,20,2);ctx.fillStyle=b.gold?\'#ffa737\':\'#d3e46d\';ctx.fillRect(x-10,y+r+5,20*(1-b.age/b.ttl),2)}\nlet x=player.x,y=player.y,a=Math.atan2(mouse.y-y,mouse.x-x),reach=70+9*levels.reach;ctx.fillStyle=\'#08170c88\';ctx.beginPath();ctx.ellipse(x,y+20,20,7,0,0,TAU);ctx.fill();rect(x-12,y-26,24,40,\'#a26334\');rect(x-9,y-29,18,5,\'#cf9752\');rect(x-12,y-22,4,32,\'#734425\');rect(x+7,y-22,3,32,\'#ce9250\');rect(x-5,y-23,2,24,\'#bc7a40\');rect(x-9,y-17,7,8,\'#f5ebc6\');rect(x+3,y-17,7,8,\'#f5ebc6\');rect(x-5+(Math.cos(a)>0?2:0),y-14,3,5,\'#152019\');rect(x+5+(Math.cos(a)>0?2:0),y-14,3,5,\'#152019\');rect(x-4,y-3,9,3,\'#38251c\');rect(x-9,y+13,6,9,\'#be844a\');rect(x+3,y+13,6,9,\'#be844a\');rect(x-13,y+21,10,4,\'#d5a36a\');rect(x+3,y+21,10,4,\'#d5a36a\');\nctx.save();ctx.translate(x,y);ctx.rotate(a+(swingFX>0?(1-swingFX/.15)*1.3-.65:0));rect(9,-3,20,6,\'#d8a972\');rect(24,-5,reach-28,10,\'#e8bf81\');rect(reach-4,-4,5,8,\'#a47443\');ctx.restore();ctx.strokeStyle=swingFX>0?\'#edffab\':\'#b9d97955\';ctx.lineWidth=swingFX>0?5:1;ctx.beginPath();ctx.arc(x,y,reach,a-.42,a+.42);ctx.stroke();\nfor(const p of particles){ctx.globalAlpha=Math.min(1,p.life*3);rect(p.x,p.y,4,4,p.c)}ctx.globalAlpha=1;ctx.font=\'bold 14px monospace\';for(const p of popups){ctx.fillStyle=p.gold?\'#ffd587\':\'#e3ff9a\';ctx.fillText(p.text,p.x,p.y)}ctx.strokeStyle=\'#e8ffad\';ctx.lineWidth=1;ctx.beginPath();ctx.arc(mouse.x,mouse.y,7,0,TAU);ctx.moveTo(mouse.x-12,mouse.y);ctx.lineTo(mouse.x-4,mouse.y);ctx.moveTo(mouse.x+4,mouse.y);ctx.lineTo(mouse.x+12,mouse.y);ctx.moveTo(mouse.x,mouse.y-12);ctx.lineTo(mouse.x,mouse.y-4);ctx.moveTo(mouse.x,mouse.y+4);ctx.lineTo(mouse.x,mouse.y+12);ctx.stroke();if(flash){ctx.fillStyle=\'#d3544544\';ctx.fillRect(0,0,W,H)}if(time>=1200){ctx.fillStyle=\'#ffb173\';ctx.font=\'bold 12px monospace\';ctx.fillText(\'MIDNIGHT STORM // SURVIVAL IS OPTIONAL\',22,34)}}\nfunction frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;if(mode===\'playing\')update(dt);draw();requestAnimationFrame(frame)}renderShop();hud();requestAnimationFrame(frame);\n</script></body></html>'

components.html(GAME_HTML, height=1450, scrolling=True)
